/**
 * GSC fix 2026-10-29: ~47K junk URLs https://www.myplumbinginc.com/?l=<number>
 * (not generated by this site; external/legacy links). 301 any request carrying
 * an `l` query param to the same path without it, in one hop, on the canonical
 * host. Do NOT block ?l= in robots.txt: Google must crawl these to see the 301.
 */
interface Ev {
  url: URL;
  req: { method: string };
}

export default async function stripLParam(event: Ev, next: () => Promise<unknown>) {
  const m = event.req.method;
  if ((m !== "GET" && m !== "HEAD") || !event.url.searchParams.has("l")) return next();
  const params = new URLSearchParams(event.url.search);
  params.delete("l");
  const qs = params.toString();
  const location = `https://www.myplumbinginc.com${event.url.pathname}${qs ? `?${qs}` : ""}`;
  return new Response(null, { status: 301, headers: { location, "cache-control": "public, max-age=86400" } });
}
